"""Generate the final evidence packet from retained records, including failures."""
from pathlib import Path
import csv,hashlib,json
BASE=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 run=BASE/'runs/c01';s=read(run/'output/summary.json');a=read(BASE/'CONFIRMATION_AUDIT.json');dev=read(BASE/'plots/phase_shape_development.json');fresh=read(BASE/'plots/phase_shape_fresh.json')
 records=list(csv.DictReader((run/'sacct.txt').read_text().splitlines(),delimiter='|'));job=next(x for x in records if x['JobID']==s['job_id']);sec=int(job['ElapsedRaw'])
 allocation={'job_id':s['job_id'],'name':job['JobName'],'state':job['State'],'node':job['NodeList'],'exit_code':job['ExitCode'],'elapsed_seconds':sec,'allocated_gpus':1,'allocated_gpu_seconds':sec,'allocated_gpu_hours':sec/3600,'registered_ceiling_gpu_hours':s['config']['compute']['gpu_hours_ceiling'],'attempts':1,'all_attempts_terminal':job['State']=='COMPLETED','source_sacct_sha256':sha(run/'sacct.txt')}
 dump(BASE/'ALLOCATION_AUDIT.json',allocation)
 result={'schema':'jcp-phase-confirm-final-v1','status':'complete_with_retained_initial_fit_qualification_failure','scientific_confirmation_qualified':a['scientific_confirmation_qualified'],'evidence_integrity_passed':a['evidence_integrity_passed'],'source_commit':s['source_commit'],'job_id':s['job_id'],'gpu':s['gpu'],'cohort':read(BASE/'COHORT_REGISTRATION.json'),'frozen_method':{'n':s['config']['n'],'rank':s['config']['rank'],'k':s['config']['k'],'settings':s['config']['test_settings'],'arms':s['config']['arms'],'solver':s['config']['solver'],'horizon':s['config']['horizon']},'fresh_qualification':s['qualification'],'initial_fit_failure':read(BASE/'IC_QUALIFICATION_DIAGNOSIS.json'),'development_plot_statistics':dev,'fresh_plot_statistics':fresh,'probes':a['probe_counts'],'allocation':allocation,'interpretation':['The head/span field-error difference persists after the declared physical-centroid alignment. This is not a pure phase-error explanation or an optimal-registration result.','Centroid concentration supports the definition of the phase diagnostic on all recorded coordinate/time points. Phase gains are mixed across cases.','Fresh trajectories, references and same-previous-state probes pass their checks, but two initial fits fail the frozen strict stationarity/selector contract. All fresh-cohort outcomes are retained and labeled incomplete formal qualification.','No changes to the model, solver tolerance or selector were made after fresh truth generation; no further cohort was opened.'],'remaining_conditional_work':'Only if a uniformly qualified fresh-cohort robustness claim is retained: repair initializer numerical robustness on exposed/training cases, freeze it again, then separately validate; this batch does not do so.','merge_status':'unmerged, decision pending','sources':{str(p.relative_to(BASE)):sha(p) for p in [run/'output/summary.json',run/'output/centroid_replay.json',BASE/'CONFIRMATION_AUDIT.json',BASE/'IC_QUALIFICATION_DIAGNOSIS.json',BASE/'PLOT_VERIFICATION.json',BASE/'PROTOCOL.md',BASE/'configs/confirm.json']}}
 dump(BASE/'FINAL_SUMMARY.json',result)
 entry=f'''### Codex — physical phase/shape plots and frozen NS confirmation\n\nCreated lane exp/2026-11-19-jcp-phase-confirm from the canonical fork, with namespace /cluster/tufts/paralab/tawal01/jcp-phase-confirm-20261119. Job {s['job_id']} completed on {s['gpu'].split(',')[0]}, charged {sec} allocated GPU-seconds ({sec/3600:.9f} GPU-hours), one attempt. Saved development trajectories were replayed only to verify physical-centroid concentration; scalar metric reproduction and checksums passed. Publication PNG/SVG/PDF figures, per-time CSV/JSON, captions, all-case panels and centroid-reliability panels are in the lane's plots/ directory.\n\nThe development paired span/head ratios of maximum evolved ordinary and centroid-aligned field error are {dev['paired']['field']['median_ratio']:.9f} and {dev['paired']['shape']['median_ratio']:.9f}. The head has lower maximum physical-centroid displacement on {dev['paired']['phase']['head_lower_count']}/{dev['cases']} cases. The field advantage persists after this reference-assisted alignment; phase-only attribution is unsupported. Concentration is reliable under the preregistered descriptive flag.\n\nThe frozen fresh cohort used {fresh['cases']} original-family cases, seed {s['config']['eval_seed']}, with exact/rounded parameter non-overlap against recorded bank/head training and development tuples. All trajectory, reference, Jacobian, operator and common-IC checks pass; all {a['probe_counts']['total']} same-previous-state probes reduce weak residual and increase physical error. However, cases {a['initial_fit_failed_case_indices']} fail the frozen strict initial-fit stationarity contract. Thus full-cohort formal confirmation remains unqualified, despite observed ordinary/aligned paired median ratios {fresh['paired']['field']['median_ratio']:.9f}/{fresh['paired']['shape']['median_ratio']:.9f} and the head's lower error on every case. The failed selected starts have costs below stationary alternatives outside the inherited floating-point tie band, while loose/strict selected initial states coincide. No selector/tolerance relaxation, case removal, model repair or new cohort followed. Optional fixed-frame manifold fits retain {a['optional_fixed_frame_head_fit_nonstationary']}/{a['optional_fixed_frame_head_fit_total']} nonstationary outcomes; they are not used in the phase/shape claim.\n\nRoot records this agent's closure in the canonical log. Evidence source and checksum audits pass; raw artifacts, source and generated figures are committed and backed up before owned remote duplicates are removed. The lane stays unmerged pending the user's decision. Separate paused/tree studies are untouched. A numerical-initializer repair followed by newly frozen validation is conditional future work only if uniformly qualified generalization is claimed.\n'''
 (BASE/'LAB_ENTRY.md').write_text(entry)
 print(json.dumps({'status':result['status'],'allocation':allocation},indent=2))
if __name__=='__main__':main()
